CREATE TABLE "utilisateurs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar(100) NOT NULL,
  "prenom" varchar(100) NOT NULL,
  "email" varchar(150) UNIQUE NOT NULL,
  "telephone" varchar(20) UNIQUE NOT NULL,
  "mot_de_passe" varchar(255) NOT NULL,
  "filiere" varchar(50),
  "niveau" varchar(20),
  "bio" text,
  "photo_profil" varchar(255),
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "competences" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer,
  "matiere" varchar(100) NOT NULL,
  "type" varchar(10)
);

CREATE TABLE "disponibilites" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer,
  "jour" varchar(20) NOT NULL,
  "heure_debut" time NOT NULL,
  "heure_fin" time NOT NULL
);

CREATE TABLE "offres_mentorat" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer,
  "matiere" varchar(100) NOT NULL,
  "format" varchar(20),
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "demandes_mentorat" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer,
  "matiere" varchar(100) NOT NULL,
  "format" varchar(20),
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "reponses" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "offre_id" integer,
  "demande_id" integer,
  "utilisateur_id" integer,
  "statut" varchar(20) DEFAULT 'en_attente',
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "matchings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mentor_id" integer,
  "mentore_id" integer,
  "score" float NOT NULL,
  "statut" varchar(20) DEFAULT 'en_attente',
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "conversations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "created_at" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "participants_conversation" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "conversation_id" integer,
  "utilisateur_id" integer
);

CREATE TABLE "messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "conversation_id" integer,
  "expediteur_id" integer,
  "contenu" text NOT NULL,
  "envoye_a" timestamp DEFAULT (CURRENT_TIMESTAMP)
);

COMMENT ON COLUMN "competences"."type" IS 'force ou lacune';

COMMENT ON COLUMN "offres_mentorat"."format" IS 'presentiel, en_ligne, les_deux';

COMMENT ON COLUMN "demandes_mentorat"."format" IS 'presentiel, en_ligne, les_deux';

COMMENT ON COLUMN "reponses"."statut" IS 'en_attente, accepte, refuse';

COMMENT ON COLUMN "matchings"."statut" IS 'en_attente, accepte, refuse';

ALTER TABLE "competences" ADD FOREIGN KEY ("utilisateur_id") REFERENCES "utilisateurs" ("id") DEFERRABLE INITIALLY IMMEDIATE;

